import{_ as p,a0 as o,w as d,s as r,I as i,x as a,a1 as t,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"面向系统管理员的 Bash 指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向系统管理员的 Bash 指南 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向系统管理员的 Bash 指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向系统管理员的 Bash 指南 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180731 A sysadmin-s guide to Bash","title":"面向系统管理员的 Bash 指南","tag":"201808","desc":""},"relativePath":"201808/20180731 A sysadmin-s guide to Bash.md","filePath":"[post].md"}'),h={name:"201808/20180731 A sysadmin-s guide to Bash.md"};function u(g,s,b,k,c,f){const e=o("Link");return d(),r("div",null,[s[34]||(s[34]=i("h1",{id:"面向系统管理员的-bash-指南",tabindex:"-1"},[a("面向系统管理员的 Bash 指南 "),i("a",{class:"header-anchor",href:"#面向系统管理员的-bash-指南","aria-label":"Permalink to “面向系统管理员的 Bash 指南”"},"​")],-1)),s[35]||(s[35]=i("blockquote",null,[i("p",null,"使 Bash 工作的更好的技巧。")],-1)),s[36]||(s[36]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/build_structure_tech_program_code_construction.png?itok=nVsiLuag",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("每个行业都有一个该行业的大师们最常使用的工具。 对于许多系统管理员来说，这个工具就是他们的 ",-1)),t(e,{href:"http://www.catb.org/jargon/html/S/shell.html"},{default:n(()=>[...s[0]||(s[0]=[a("shell",-1)])]),_:1}),s[2]||(s[2]=a("。 在大多数 Linux 和其他类 Unix 系统上，默认的 shell 是 Bash。",-1))]),s[37]||(s[37]=l(`<p>Bash 是一个相当古老的程序——它起源于 20 世纪 80 年代后期——但它建立在更多更老的 shell 上，比如 C shell（csh），csh 至少是它 10 年前的前辈了。 因为 shell 的概念是那么古老，所以有大量的神秘知识等待着系统管理员去吸收领悟，使其生活更轻松。</p><p>我们来看看一些基础知识。</p><p>在某些时候，谁曾经无意中以 root 身份运行命令并导致某种问题？ <em>举手</em></p><p>我很确定我们很多人一度都是那个人。 这很痛苦。 这里有一些非常简单的技巧可以防止你再次碰上这类问题。</p><h3 id="使用别名" tabindex="-1">使用别名 <a class="header-anchor" href="#使用别名" aria-label="Permalink to “使用别名”">​</a></h3><p>首先，为 <code>mv</code> 和 <code>rm</code> 等命令设置别名，指向 <code>mv -i</code> 和 <code>rm -i</code>。 这将确保在运行 <code>rm -f /boot</code> 时至少需要你确认。 在 Red Hat 企业版 Linux 中，如果你使用 root 帐户，则默认设置这些别名。</p><p>如果你还要为普通用户帐户设置这些别名，只需将这两行放入家目录下名为 <code>.bashrc</code> 的文件中（这些也适用于 <code>sudo</code> ）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mv=&#39;mv -i&#39;</span></span>
<span class="line"><span>alias rm=&#39;rm -i&#39;</span></span></code></pre></div><h3 id="让你的-root-提示符脱颖而出" tabindex="-1">让你的 root 提示符脱颖而出 <a class="header-anchor" href="#让你的-root-提示符脱颖而出" aria-label="Permalink to “让你的 root 提示符脱颖而出”">​</a></h3><p>你可以采取的防止意外发生的另一项措施是确保你很清楚在使用 root 帐户。 在日常工作中，我通常会让 root 提示符从日常使用的提示符中脱颖而出。</p><p>如果将以下内容放入 root 的家目录中的 <code>.bashrc</code> 文件中，你将看到一个黑色背景上的红色的 root 提示符，清楚地表明你（或其他任何人）应该谨慎行事。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PS1=&quot;\\[$(tput bold)$(tput setab 0)$(tput setaf 1)\\]\\u@\\h:\\w # \\[$(tput sgr0)\\]&quot;</span></span></code></pre></div><p>实际上，你应该尽可能避免以 root 用户身份登录，而是通过 <code>sudo</code> 运行大多数系统管理命令，但这是另一回事。</p><p>使用了一些小技巧用于防止使用 root 帐户时的“不小心的副作用”之后，让我们看看 Bash 可以帮助你在日常工作中做的一些好事。</p><h3 id="控制你的历史" tabindex="-1">控制你的历史 <a class="header-anchor" href="#控制你的历史" aria-label="Permalink to “控制你的历史”">​</a></h3><p>你可能知道在 Bash 中你按向上的箭头时能看见和重新使用你之前所有（好吧，大多数）的命令。这是因为这些命令已经保存到了你家目录下的名为 <code>.bash_history</code> 的文件中。这个历史文件附带了一组有用的设置和命令。</p><p>首先，你可以通过键入 <code>history</code> 来查看整个最近的命令历史记录，或者你可以通过键入 <code>history 30</code> 将其限制为最近 30 个命令。不过这技巧太平淡无奇了（LCTT 译注： vanilla 原为香草，后引申没拓展的、标准、普通的，比如 vanilla C++ compiler 意为标准 C++ 编译器）。 你可以更好地控制 Bash 保存的内容以及保存方式。</p><p>例如，如果将以下内容添加到 <code>.bashrc</code>，那么任何以空格开头的命令都不会保存到历史记录列表中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTCONTROL=ignorespace</span></span></code></pre></div><p>如果你需要以明文形式将密码传递给一个命令，这就非常有用。 （是的，这太可怕了，但它仍然会发生。）</p><p>如果你不希望经常执行的命令充斥在历史记录中，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTCONTROL=ignorespace:erasedups</span></span></code></pre></div><p>这样，每次使用一个命令时，都会从历史记录文件中删除之前出现的所有相同命令，并且只将最后一次调用保存到历史记录列表中。</p><p>我特别喜欢的历史记录设置是 <code>HISTTIMEFORMAT</code> 设置。 这将在历史记录文件中在所有的条目前面添加上时间戳。 例如，我使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTTIMEFORMAT=&quot;%F %T  &quot;</span></span></code></pre></div><p>当我输入 <code>history 5</code> 时，我得到了很好的完整信息，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1009  2018-06-11 22:34:38  cat /etc/hosts</span></span>
<span class="line"><span>1010  2018-06-11 22:34:40  echo $foo</span></span>
<span class="line"><span>1011  2018-06-11 22:34:42  echo $bar</span></span>
<span class="line"><span>1012  2018-06-11 22:34:44  ssh myhost</span></span>
<span class="line"><span>1013  2018-06-11 22:34:55  vim .bashrc</span></span></code></pre></div><p>这使我更容易浏览我的命令历史记录并找到我两天前用来建立到我家实验室的 SSH 连接（我一次又一次地忘记......）。</p><h3 id="bash-最佳实践" tabindex="-1">Bash 最佳实践 <a class="header-anchor" href="#bash-最佳实践" aria-label="Permalink to “Bash 最佳实践”">​</a></h3><p>我将在编写 Bash 脚本时最好的（或者至少是好的，我不要求无所不知）11 项实践列出来。</p><p>11、 Bash 脚本可能变得复杂，不过注释也很方便。 如果你在考虑是否要添加注释，那就添加一个注释。 如果你在周末之后回来并且不得不花时间搞清楚你上周五想要做什么，那你是忘了添加注释。</p><p>10、 用花括号括起所有变量名，比如 <code>\${myvariable}</code>。 养成这个习惯可以使用 <code>\${variable}_suffix</code> 这种用法了，还能提高整个脚本的一致性。</p><p>9、 计算表达式时不要使用反引号；请改用 <code>$()</code> 语法。 所以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for  file in $(ls); do</span></span></code></pre></div><p>而不使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for  file in \`ls\`; do</span></span></code></pre></div><p>前一个方式是可嵌套的，更易于阅读的，还能让一般的系统管理员群体感到满意。 不要使用反引号。</p><p>8、 一致性是好的。 选择一种风格并在整个脚本中坚持下去。 显然，我喜欢人们选择 <code>$()</code> 语法而不是反引号，并将其变量包在花括号中。 我更喜欢人们使用两个或四个空格而不是制表符来缩进，但即使你选择了错误的方式，也要一贯地错下去。</p>`,38)),i("p",null,[s[5]||(s[5]=a("7、 为 Bash 脚本使用适当的",-1)),i("ruby",null,[t(e,{href:"https://linux.cn/article-3664-1.html"},{default:n(()=>[...s[3]||(s[3]=[a("释伴",-1)])]),_:1}),s[4]||(s[4]=i("rt",null,"shebang",-1))]),s[6]||(s[6]=a("（LCTT 译注：",-1)),s[7]||(s[7]=i("strong",null,"Shebang",-1)),s[8]||(s[8]=a("，也称为 ",-1)),s[9]||(s[9]=i("strong",null,"Hashbang",-1)),s[10]||(s[10]=a(" ，是一个由井号和叹号构成的字符序列 ",-1)),s[11]||(s[11]=i("code",null,"#!",-1)),s[12]||(s[12]=a(" ，其出现在文本文件的第一行的前两个字符。 在文件中存在释伴的情况下，类 Unix 操作系统的程序载入器会分析释伴后的内容，将这些内容作为解释器指令，并调用该指令，并将载有释伴的文件路径作为该解释器的参数）。 因为我正在编写Bash脚本，只打算用 Bash 执行它们，所以我经常使用 ",-1)),s[13]||(s[13]=i("code",null,"#!/usr/bin/bash",-1)),s[14]||(s[14]=a(" 作为我的释伴。 不要使用 ",-1)),s[15]||(s[15]=i("code",null,"#!/bin/sh",-1)),s[16]||(s[16]=a(" 或 ",-1)),s[17]||(s[17]=i("code",null,"#!/usr/bin/sh",-1)),s[18]||(s[18]=a("。 你的脚本会被执行，但它会以兼容模式运行——可能会产生许多意外的副作用。 （当然，除非你想要兼容模式。）",-1))]),s[38]||(s[38]=l(`<p>6、 比较字符串时，在 <code>if</code> 语句中给变量加上引号是个好主意，因为如果你的变量是空的，Bash 会为这样的行抛出一个错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ \${myvar} == &quot;foo&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;bar&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>对于这样的行，将判定为 <code>false</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ &quot;\${myvar}&quot; == &quot;foo&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;bar&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>此外，如果你不确定变量的内容（例如，在解析用户输入时），请给变量加引号以防止解释某些特殊字符，并确保该变量被视为单个单词，即使它包含空格。</p><p>5、 我想这是一个品味问题，但我更喜欢使用双等号（ <code>==</code> ），即使是比较 Bash 中的字符串。 这是一致性的问题，尽管对于字符串比较，只有一个等号会起作用，我的思维立即变为“单个 <code>=</code> 是一个赋值运算符！”</p><p>4、 使用适当的退出代码。 确保如果你的脚本无法执行某些操作，则会向用户显示已写好的失败消息（最好提供解决问题的方法）并发送非零退出代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># we have failed</span></span>
<span class="line"><span>echo &quot;Process has failed to complete, you need to manually restart the whatchamacallit&quot;</span></span>
<span class="line"><span>exit 1</span></span></code></pre></div><p>这样可以更容易地以编程方式从另一个脚本调用你的脚本并验证其成功完成。</p><p>3、 使用 Bash 的内置机制为变量提供合理的默认值，或者如果未定义你希望定义的变量，则抛出错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># this sets the value of $myvar to redhat, and prints &#39;redhat&#39;</span></span>
<span class="line"><span>echo \${myvar:=redhat}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># this throws an error reading &#39;The variable myvar is undefined, dear reader&#39; if $myvar is undefined</span></span>
<span class="line"><span>\${myvar:?The variable myvar is undefined, dear reader}</span></span></code></pre></div><p>2、 特别是如果你正在编写大型脚本，或者是如果你与其他人一起开发该大型脚本，请考虑在函数内部定义变量时使用 <code>local</code> 关键字。 <code>local</code> 关键字将创建一个局部变量，该变量只在该函数中可见。 这限制了变量冲突的可能性。</p><p>1、 每个系统管理员有时必须这样做：在控制台上调试一些东西，可能是数据中心的真实服务器，也可能是虚拟化平台的虚拟服务器。 如果你必须以这种方式调试脚本，你会感谢你自己记住了这个：不要让你的脚本中的行太长！</p><p>在许多系统上，控制台的默认宽度仍为 80 个字符。 如果你需要在控制台上调试脚本并且该脚本有很长的行，那么你将成为一个悲伤的熊猫。 此外，具有较短行的脚本—— 默认值仍为 80 个字符——在普通编辑器中也更容易阅读和理解！</p><p>我真的很喜欢 Bash。 我可以花几个小时写这篇文章或与其他爱好者交流优秀的技巧。 就希望你们能在评论中留下赞美。</p><hr>`,17)),i("p",null,[s[20]||(s[20]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/18/7/admin-guide-bash"},{default:n(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/18/7/admin-guide-bash",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/wzzrd"},{default:n(()=>[...s[21]||(s[21]=[a("Maxim Burgerhout",-1)])]),_:1}),s[26]||(s[26]=a(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 译者：",-1)),t(e,{href:"https://github.com/Flowsnow"},{default:n(()=>[...s[23]||(s[23]=[a("Flowsnow",-1)])]),_:1}),s[28]||(s[28]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[31]||(s[31]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[30]||(s[30]=[a("Linux中国",-1)])]),_:1}),s[33]||(s[33]=a(" 荣誉推出",-1))])])}const C=p(h,[["render",u]]);export{v as __pageData,C as default};
